using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalReferencePineRebuild {
const string D="Assets/Scenes/Oasis/CoastalTerrain";
static CoastalReferencePineRebuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalReferencePineRebuild.request"))return;try{File.Delete("CoastalReferencePineRebuild.request");}catch(IOException){return;}Run();}
class Tree{public Vector3 anchor;public float height;}
class Geometry {
public List<Vector3> p=new List<Vector3>(),n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Vector4> wind=new List<Vector4>();public List<Color> color=new List<Color>();public List<int> ids=new List<int>();public Tree tree;
int Vertex(Vector3 pos,Vector2 tex,Color col,Vector3 normal){int i=p.Count;p.Add(pos);uv.Add(tex);color.Add(col);n.Add(normal);wind.Add(new Vector4(Mathf.Clamp01((pos.y-tree.anchor.y)/tree.height),tree.anchor.x,tree.anchor.z,0));return i;}
public void Wood(Vector3 a,Vector3 b,float ra,float rb,int sides){var dir=(b-a).normalized;var right=Vector3.Cross(dir,Mathf.Abs(dir.y)>.9f?Vector3.forward:Vector3.up).normalized;var side=Vector3.Cross(dir,right);var brown=new Color(.105f,.066f,.036f,0);int first=p.Count;for(int ring=0;ring<2;ring++)for(int k=0;k<sides;k++){float angle=k*Mathf.PI*2/sides;var radial=right*Mathf.Cos(angle)+side*Mathf.Sin(angle);Vertex((ring==0?a:b)+radial*(ring==0?ra:rb),Vector2.zero,brown,radial);}for(int k=0;k<sides;k++){int j=(k+1)%sides;ids.AddRange(new[]{first+k,first+sides+k,first+j,first+j,first+sides+k,first+sides+j});}}
public void Needles(Vector3 center,Vector3 direction,float radius,float roll,float shade,bool far){var across=direction.normalized;var horizontal=Vector3.Cross(across,Vector3.up).normalized;if(horizontal.sqrMagnitude<.1f)horizontal=Vector3.right;var vertical=Vector3.Cross(horizontal,across).normalized;int planes=far?1:2;for(int plane=0;plane<planes;plane++){float tilt=(roll+(plane==0?22:94))*Mathf.Deg2Rad;var side=(horizontal*Mathf.Cos(tilt)+vertical*Mathf.Sin(tilt)).normalized;var a=across*radius;var b=side*radius;var normal=Vector3.Cross(across,side).normalized;int first=p.Count;var tint=new Color(shade*.89f,shade,shade*.85f,1);Vertex(center-a-b,new Vector2(.005f,.005f),tint,normal);Vertex(center+a-b,new Vector2(.995f,.005f),tint,normal);Vertex(center-a+b,new Vector2(.005f,.995f),tint,normal);Vertex(center+a+b,new Vector2(.995f,.995f),tint,normal);ids.AddRange(new[]{first,first+2,first+1,first+1,first+2,first+3});}}
public void Save(Mesh mesh){mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(p);mesh.SetNormals(n);mesh.SetUVs(0,uv);mesh.SetUVs(1,wind);mesh.SetColors(color);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(1);mesh.bounds=bounds;mesh.name="Reference forest pine with branching needle sprays v6";EditorUtility.SetDirty(mesh);}}
static List<Tree> ReadTrees(Mesh mesh){var p=mesh.vertices;var w=new List<Vector4>();mesh.GetUVs(1,w);var groups=new Dictionary<Vector2,List<int>>();for(int i=0;i<p.Length;i++){var key=new Vector2(w[i].y,w[i].z);if(!groups.ContainsKey(key))groups[key]=new List<int>();groups[key].Add(i);}return groups.Select(g=>new Tree{anchor=new Vector3(g.Key.x,g.Value.Min(i=>p[i].y),g.Key.y),height=Mathf.Clamp(g.Value.Max(i=>p[i].y)-g.Value.Min(i=>p[i].y),9,18)}).ToList();}
static int nearTri,farTri,treeCount;static Vector3 previewAnchor;static float previewHeight;static float best=float.MaxValue;
static void Build(Mesh mesh,bool far,string path){if(mesh.name=="Reference forest pine with branching needle sprays v6")return;var trees=ReadTrees(mesh);var geo=new Geometry();foreach(var tree in trees){geo.tree=tree;float h=tree.height;var rng=new System.Random(Mathf.RoundToInt(tree.anchor.x*71+tree.anchor.z*139)+(path.Contains("Pine 1")?41:path.Contains("Pine 2")?97:0));Func<float> r=()=> (float)rng.NextDouble();var lean=new Vector3((r()-.5f)*h*.012f,0,(r()-.5f)*h*.012f);var trunkTop=tree.anchor+Vector3.up*h+lean;geo.Wood(tree.anchor,trunkTop,h*.011f,h*.0009f,far?4:7);
int levels=far?6:11;for(int level=0;level<levels;level++){float t=level/(float)(levels-1);float y=h*(.27f+.69f*t)+(r()-.5f)*h*.022f;float envelope=Mathf.Pow(1-t,.65f)*h*.19f+h*.022f;float phase=r()*360;int count=far?3:(t>.87f?3:5);for(int branch=0;branch<count;branch++){float angle=(phase+branch*360f/count+(r()-.5f)*28)*Mathf.Deg2Rad;var radial=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle));var basePos=tree.anchor+lean*(y/h)+Vector3.up*(y+(r()-.5f)*h*.025f);float length=envelope*(.74f+r()*.36f);var tip=basePos+radial*length+Vector3.up*h*(-.025f+r()*.033f);if(!far)geo.Wood(basePos,tip,h*.0021f*(1-t*.7f),h*.00035f,4);
int sprays=far?2:4;for(int s=0;s<sprays;s++){float along=.32f+s/(float)Mathf.Max(1,sprays-1)*.65f;var main=Vector3.Lerp(basePos,tip,along);var side=Vector3.Cross(radial,Vector3.up);float sign=s%2==0?1:-1;var twigDir=(radial*.65f+side*sign*.6f+Vector3.up*(r()*.12f-.12f)).normalized;float twigLength=length*(.23f+r()*.1f)*(1-along*.35f);var twigTip=main+twigDir*twigLength;if(!far)geo.Wood(main,twigTip,h*.0009f,h*.00025f,3);float radius=Mathf.Max(h*.027f,twigLength*.66f);geo.Needles(Vector3.Lerp(main,twigTip,.65f),twigDir,radius,(r()-.5f)*30,.72f+r()*.22f,far);if(!far&&s==2)geo.Needles(twigTip+radial*radius*.22f,radial,radius*.8f,(r()-.5f)*30,.8f+r()*.14f,false);}}}
geo.Needles(trunkTop-Vector3.up*h*.024f,Vector3.up,h*.039f,17,.88f,far);if(!far){float distance=Vector2.Distance(new Vector2(tree.anchor.x,tree.anchor.z),new Vector2(830,180));if(distance<best&&tree.anchor.x>815){best=distance;previewAnchor=tree.anchor;previewHeight=h;}}treeCount++;}if(far)farTri+=geo.ids.Count/3;else nearTri+=geo.ids.Count/3;geo.Save(mesh);}
static void Run(){try{var seen=new HashSet<Mesh>();int prefabs=0;foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{D+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(guid);if(!Path.GetFileName(path).StartsWith("Pine_")&&!Path.GetFileName(path).StartsWith("Natural Pine"))continue;var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>())if(seen.Add(f.sharedMesh))Build(f.sharedMesh,f.name=="Distant",path);prefab.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);prefabs++;}var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Details/Shared 3D Forest Pine.mat");mat.SetFloat("_Cutoff",.28f);mat.SetColor("_Tint",new Color(.93f,1,.94f));mat.SetFloat("_WindStrength",.25f);mat.SetFloat("_WindSpeed",.95f);mat.SetFloat("_PreviewTime",-1);mat.enableInstancing=true;EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Rebuilt-Reference-Forest-Pines"});if(best<float.MaxValue)capture.Invoke(null,new object[]{scene,previewAnchor+new Vector3(-9,previewHeight*.58f,-12),previewAnchor+Vector3.up*previewHeight*.54f,"Rebuilt-Pine-Closeup"});File.WriteAllText("FinalEnvironmentRoadReview/ReferencePineRebuildReport.txt","SUCCESS prefabs="+prefabs+" meshes="+seen.Count+" trees across LODs="+treeCount+" near triangles="+nearTri+" distant triangles="+farTri+"; actual 3D trunks/main branches/twigs; many smaller isotropic PNG needle sprays with branch-local orientation; near/distant silhouettes; preserved anchored GPU wind; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/ReferencePineRebuildReport.txt","FAILED "+e);Debug.LogException(e);}}
}
